INSERT INTO public.questions (type, chapter, content, options, correct_answer, explanation) VALUES
('single', 'chapter_single', '在测量过程中，如果CO+CO₂ 的浓度值小于(     )，或发动机熄火，应终止检测?', '{"A": "0.04", "B": "0.05", "C": "0.06", "D": "0.07"}'::jsonb, 'C', ''),
('single', 'chapter_single', '在进行双怠速法测试时，对发动机的水温或机油温度有什么要求?', '{"A": "应不低于60℃", "B": "应不低于70℃", "C": "应不低于80℃或达到车辆使用说明书规定\n的热状态", "D": "没有具体要求"}'::jsonb, 'C', ''),
('single', 'chapter_single', '在双怠速法测试过程中，对于多排气管车辆应如何操作以获得准确的测试结果?', '{"A": "只测量一个排气管的排放值即可", "B": "测量所有排气管的排放值，并取最大值作为结果", "C": "测量所有排气管的排放值，并计算它们的\n算术平均值作为结果", "D": "随机选择一个排气管进行测量即可"}'::jsonb, 'C', ''),
('single', 'chapter_single', '经校准后的排气污染物检测仪在对车辆进行检测后，检测结果为负数或者零，应记录和报告为(     )。', '{"A": "未检出", "B": "负数或者零", "C": "检查仪器是否出现故障", "D": "以上答案均正确"}'::jsonb, 'A', ''),
('single', 'chapter_single', '单一燃料汽车和两用燃料汽车都能燃用汽油和一种气体燃料，它们间的区别为汽油油箱的大小，当汽油箱大于(    )升时，这类汽车就是双燃料汽车，该类汽车在进行定期检验时应分别对两种燃料进行排放检验。', '{"A": "10", "B": "15", "C": "18", "D": "20"}'::jsonb, 'B', ''),
('single', 'chapter_single', 'GB3847-2018规定的加载减速法轮边功率限值的测量工况为(      )。', '{"A": "功率扫描过程获得的最大轮边功率", "B": "100%Ve1MaxHP测试工况", "C": "90%VelMaxHP测试工况", "D": "80%VelMaxHP测试工况"}'::jsonb, 'B', ''),
('single', 'chapter_single', '加载减速法功率扫描过程中，经修正的轮边功率测量结果不得低于制造厂规定的发动机额定功率的(     ),否则判定为检验结果不合格。', '{"A": "0.3", "B": "0.4", "C": "0.5", "D": "0.6"}'::jsonb, 'B', ''),
('single', 'chapter_single', '自由加速不透光烟度法检测重型柴油车，将油门踏板放开后至少等待(    ),再进行下一次自由加速过程。', '{"A": "5秒", "B": "10秒", "C": "15秒", "D": "20秒"}'::jsonb, 'B', ''),
('single', 'chapter_single', '加载减速检测结束后，应提醒司机在关闭发动机之前，将车辆置于怠速状态至少(    )。', '{"A": "30秒", "B": "60秒", "C": "90秒", "D": "120秒"}'::jsonb, 'B', ''),
('single', 'chapter_single', '(    )是模拟汽车行驶时产生的惯力，模拟汽车惯力，使检测过程更接近于实际行驶。', '{"A": "惯量模拟装置", "B": "功率吸收装置", "C": "制动装置", "D": "废气吸收装置"}'::jsonb, 'A', ''),
('single', 'chapter_single', '(    )测量滚筒的转速再传送给计算机，再由计算机根据滚筒直径和转速换算出车辆直线行驶的速度。', '{"A": "速度传感器", "B": "涡流机", "C": "力传感器", "D": "举升器"}'::jsonb, 'A', ''),
('single', 'chapter_single', '根据HJ1237-2021规定，测功机日常检查时，以下哪个项目(    )需要每天开机时做测试检查。', '{"A": "加载滑行", "B": "惯量测试", "C": "力校准", "D": "速度检查"}'::jsonb, 'A', ''),
('single', 'chapter_single', '轻型柴油车排放检测用底盘测功机的滚筒直径应为(    )mm。', '{"A": "210±2", "B": "210±5", "C": "218±2", "D": "218±5"}'::jsonb, 'C', ''),
('single', 'chapter_single', '加载减速法在检测期间，如果环境温度超过(    )℃,应自动中止检测，并且显示以下信息：“检测暂停-检测环境温度状况不适合进行检测。', '{"A": "30", "B": "35", "C": "42", "D": "45"}'::jsonb, 'C', ''),
('single', 'chapter_single', '加载减速法使用前进档驱动被检车辆，选择合适的档位，使油门处于全开位置时，测功机指示的车速接近(    )km/h,但不得超过(    )km/h(对装有自动变速器的车辆，应注意不要在超速档下进行测量),完成加载减速的自动试验过程。', '{"A": "50、70", "B": "70、90", "C": "70、100", "D": "90、100"}'::jsonb, 'C', ''),
('single', 'chapter_single', '加载减速测试时，在车辆散热器前方(    )左右处放置强制冷却风机，以保证车辆在检测过程中发动机冷却系统能有效地工作。', '{"A": "1m", "B": "2m", "C": "3m", "D": "5m"}'::jsonb, 'A', ''),
('single', 'chapter_single', '违反《中华人民共和国大气污染防治法》规定，伪造机动车、非道路移动机械排放检验结果或者出具虚假排放检验报告的，由县级以上人民政府环境保护主管部门没收违法所得，并处(     )的罚款。', '{"A": "一万元以上五元以下", "B": "五元以上十万元以下", "C": "十万元以上五十万元以下", "D": "五十万元以上八十万元以下"}'::jsonb, 'C', ''),
('single', 'chapter_single', '排气分析仪应(    )开始检测前进行一次低量程标准气体检查，若检查不能通过，则应使用高浓度标准气体进行标定，然后使用低浓度标准气体进行检查，直到满足要求为止。', '{"A": "每天", "B": "每周", "C": "每次", "D": "每月"}'::jsonb, 'A', ''),
('single', 'chapter_single', '车载诊断(OBD)系统检查程序读 取(OBD)数据如果发现受检车辆的 就 绪 状 态 未 完 成 项 超 过 (    )项，应要求车主充分行驶后再进行复检。', '{"A": "4", "B": "3", "C": "2", "D": "5"}'::jsonb, 'C', ''),
('single', 'chapter_single', 'GB18285-2018中关于排气分析仪的名义HC丙烷当量系数(PEF),以下数值在标准规定的PEF范围内的。', '{"A": "0.391", "B": "0.491", "C": "0.591", "D": "0.691"}'::jsonb, 'B', ''),
('single', 'chapter_single', '对于0₂分析仪，如果响应时间在(    )天内都超过(    )s,认为检查失败，应锁止分析仪，对系统进行检查，必要时应0₂更换传感器。', '{"A": "5;10", "B": "5;12", "C": "7;10", "D": "7;12"}'::jsonb, 'D', ''),
('single', 'chapter_single', '排放检验不合格的，维修后复检时，应采用(    )环保检验的排气污染物排放检测方法进行。', '{"A": "首次", "B": "复检", "C": "指定的", "D": "合理的"}'::jsonb, 'A', ''),
('single', 'chapter_single', 'X城市车辆跨地区到Y城市进行排放检验(X城市实施GB 18285标准中限值a,Y城市已实施GB 18285标准中限值b),则该车应执行的限值。', '{"A": "限值a", "B": "限值a和限值\nb的平均值", "C": "限值b", "D": "限值a和限值\nb中大的"}'::jsonb, 'C', ''),
('single', 'chapter_single', '每次检测前不透光烟度计应分别进行(    )不透光度检查。', '{"A": "30%和50%", "B": "30%和70%", "C": "50%和70%", "D": "0%和100%"}'::jsonb, 'D', ''),
('single', 'chapter_single', '加载减速法检测使用前进挡驱动被检车辆，选择合适的档位，使油门踏板处于全开位置时，测功机指示的车速最接近(    )。', '{"A": "50km/h,但不能超过70 km/h", "B": "50km/h,但不能超过\n100km/h", "C": "70km/h,但不能超过100km/h", "D": "70km/h,但不能超过\n120km/h"}'::jsonb, 'C', ''),
('single', 'chapter_single', '测功机应有滚筒转速测量装置，在车速测量范围内，其测量准确度应达到(    ) 。', '{"A": "±1km/h", "B": "±2km/h", "C": "±0.1km/h", "D": "±0.2km/h"}'::jsonb, 'D', ''),
('single', 'chapter_single', '尾气分析仪取样探头所用材料应能耐受的排气温度(     )。', '{"A": "600℃", "B": "500℃", "C": "400℃", "D": "300℃"}'::jsonb, 'A', ''),
('single', 'chapter_single', '不透光烟度计示值误差技术要求为：对每一标准滤光片值，以不透光度的线性分度值为计量单位，均值的绝对误差不超过±(    )%。', '{"A": "1", "B": "3", "C": "2", "D": "4"}'::jsonb, 'C', ''),
('single', 'chapter_single', '在查验注册登记车辆时，除了环保随车清单，还需要检查什么?', '{"A": "车辆的轮胎压力", "B": "车辆的油箱容量", "C": "车辆污染控制装置与环保信息随车清单是否一致", "D": "车辆的内部装饰"}'::jsonb, 'C', ''),
('single', 'chapter_single', '如果在用汽车出现明显烧机油现象，应该怎么做?', '{"A": "立刻进行尾气检测", "B": "要求车主进行维修", "C": "继续进行正常行驶", "D": "忽略该现象"}'::jsonb, 'B', ''),
('single', 'chapter_single', '在进行排气污染物检验时，能否断开0BD诊断仪?', '{"A": "能", "B": "不能", "C": "视情况而定", "D": "无所谓"}'::jsonb, 'B', ''),
('single', 'chapter_single', '对于有手动选择行驶模式的混合动力电动汽车，在注册登记和在用汽车测试时应切换到哪种模式?', '{"A": "纯电模式", "B": "混合动力模式", "C": "最大燃料消耗模式", "D": "自动模式"}'::jsonb, 'C', ''),
('single', 'chapter_single', '在进行混合动力电动汽车的排放测试过程中，如果发动机自动熄火并切换到纯电模式，测试应如何进行。', '{"A": "立即中止测试", "B": "等待发动机重新启动后继续测试", "C": "无须中止测试，应进行至测试结束", "D": "重新开始测试"}'::jsonb, 'C', ''),
('single', 'chapter_single', '自由加速测量时，发动机应达到什么转速?', '{"A": "怠速转速", "B": "中等转速", "C": "高速转速", "D": "额定转速"}'::jsonb, 'D', ''),
('single', 'chapter_single', '自由加速法检测吹拂排气系统的目的是什么?', '{"A": "清洁排气系统内部", "B": "检查排气系统是否漏气", "C": "清扫排气系统中的残留污染物", "D": "提高排气系统的效率"}'::jsonb, 'C', ''),
('single', 'chapter_single', '柴油车加载减速检测过程中，如果冷却液温度超出了规定的温度范围，应如何操作?', '{"A": "继续检测", "B": "暂停检测并让发动机怠速运转直至温度恢复", "C": "立即停止检测并关闭发动机", "D": "加大油门以加快检测进度"}'::jsonb, 'B', ''),
('single', 'chapter_single', '柴油车加载减速检验时检测员在试验过程中应实时监控哪些参数?', '{"A": "发动机转速和车速", "B": "发动机冷却液温度和机油压力", "C": "车辆排放浓度和噪声水平", "D": "轮胎气压和刹车性能"}'::jsonb, 'B', ''),
('single', 'chapter_single', '在加载减速检测的哪个阶段需要记录发动机的最大转速?', '{"A": "检测开始前", "B": "检测过程中", "C": "检测结束后", "D": "无需记录"}'::jsonb, 'A', ''),
('single', 'chapter_single', '加载减速工况法在速度控制模式下，当转鼓速度大于计算的VelMaxHP时，速度变化率每秒不得超过(     )。', '{"A": "±0.1 km/h", "B": "±0.5 km/h", "C": "±1.0 km/h", "D": "±2.0 km/h"}'::jsonb, 'B', ''),
('single', 'chapter_single', '哪种情况下，检测程序应中止并显示“检测停止-排放数据异常，请检查取样管”?', '{"A": "排气中CO₂ 的实测浓度高于2.0%", "B": "排气中CO的浓度高于\n1.0%", "C": "排气中CO₂ 的实测浓度低于2.0%", "D": "排气中NOx的浓度高于\n0.1%"}'::jsonb, 'C', ''),
('single', 'chapter_single', '加载减速测试期间，从何时开始到排放测试结束，驾驶员不得换挡?', '{"A": "自功率扫描开始", "B": "自加载减速开始", "C": "自预热开始", "D": "自测试准备开始"}'::jsonb, 'A', ''),
('single', 'chapter_single', '加载减速测试期间，若在加载减速过程中发生滑移，控制系统首先应该怎么做?', '{"A": "立即切断PAU电流", "B": "提醒驾驶员检测无效", "C": "降低PAU电流", "D": "闪烁显示屏"}'::jsonb, 'C', ''),
('single', 'chapter_single', '注册登记检验中，若污染物控制装置型号不可见，应如何记录?', '{"A": "记录“信息不可见 ”", "B": "无需记录，跳过此步骤", "C": "通过其他途径查询并记录", "D": "结束本次检验"}'::jsonb, 'A', ''),
('single', 'chapter_single', '对于无法通过油门踏板调节转速的混合动力电动汽车，采用双怠速法检测时应如何操作?', '{"A": "只进行怠速工况检测", "B": "跳过怠速工况直接进行高怠速检测", "C": "采用维修模式强制启动高怠速检测", "D": "不进行双怠速法检测"}'::jsonb, 'A', ''),
('single', 'chapter_single', '检测线视频监控要求中，关于重型柴油车和重型燃气车检测线的特别规定是什么?', '{"A": "应配备能够清晰拍摄取样管插入及拔取过程的移动式摄像机", "B": "视频监控设备必须具备夜视功能", "C": "检测线前后两端必须各安装三台以上的监\n控摄像头", "D": "视频监控画面必须实时传输至市级生态环境主管部门"}'::jsonb, 'A', ''),
('single', 'chapter_single', '在进行排气污染物检测时，对于装有怠速启停功能的车辆，正确的做法是：', '{"A": "必须拆除启停装置后再进行检测", "B": "在检测前务必手动关闭该功能", "C": "若无法关闭该功能，则检测结果视为无效", "D": "启停功能不影响检测结果，无需特别操作"}'::jsonb, 'B', ''),
('single', 'chapter_single', '按照HJ 1238—2021的规定，检验过程中，若检验数据异常导致检验无法进行或可能影响检验准确性，设备软件应如何应对?', '{"A": "自动停止检验流程，锁定设备", "B": "继续检验直至完成，并在报告中标注异常", "C": "要求检验人员手动解决异常后重启检验", "D": "强制修改异常数据使其符合正常范围"}'::jsonb, 'A', ''),
('single', 'chapter_single', '底盘测功机的功率吸收装置的作用是什么?', '{"A": "模拟风阻", "B": "模拟道路阻力", "C": "模拟车辆加速", "D": "模拟车辆制动"}'::jsonb, 'B', ''),
('single', 'chapter_single', '每次测试开始前2分钟内，排放分析仪应自动完成哪些检查?', '{"A": "零点校正和环境空气测定", "B": "对背景空气浓度取样", "C": "HC残留量的检查", "D": "所有以上内容"}'::jsonb, 'D', ''),
('single', 'chapter_single', '简易瞬态工况法测试时，测试场地的环境温度超过多少度时，应启动冷却风机?', '{"A": "20℃", "B": "22℃", "C": "25℃", "D": "30℃"}'::jsonb, 'B', '');
INSERT INTO public.questions (type, chapter, content, options, correct_answer, explanation) VALUES
('single', 'chapter_single', 'GB18285-2018定义：过量空气系数λ是指燃烧1kg燃料实际供给的空气量与理论上完全燃烧所需空气量的质量比，若λ=0.98,说明实际空气量与理论空气量的关系为(     )。', '{"A": "实际量>理论量", "B": "实际量<理论\n量", "C": "实际量=理论\n量", "D": "以上均有可能"}'::jsonb, 'B', ''),
('single', 'chapter_single', '检验检测机构或其所在法人组织还从事检验检测(    )活动的，检验检测机构应当独立运作，并识别、消除与其他部门或岗位可能存在影响其判断的独立性和诚实性的风险。', '{"A": "相关的", "B": "规定的", "C": "临时的", "D": "以外的"}'::jsonb, 'D', ''),
('single', 'chapter_single', '检验检测机构及其人员应当对其在检验检测活动中所知悉的(    )负有保密义务，并制定实施相应的保密。', '{"A": "机构秘密", "B": "国家秘密", "C": "商业秘密", "D": "国家秘密、商业秘密"}'::jsonb, 'D', ''),
('single', 'chapter_single', '检验检测机构与其人员建立劳动关系应当符合(    )的有关规定，法律、行政法规对检验检测人员执业资格或者禁止从业另有规定的，依照其规定。', '{"A": "《中华人民共和国劳动法》", "B": "《中华人民共和国劳动合同法》", "C": "《中华人民共和国劳动法》《中华人民共\n和国劳动合同法》", "D": "劳动合同法"}'::jsonb, 'C', ''),
('single', 'chapter_single', '检验检测报告授权签字人具有(    )技术职称或者同等能力。', '{"A": "中级", "B": "中级及以上相关专业", "C": "高级", "D": "高级及以上相关专业"}'::jsonb, 'B', ''),
