INSERT INTO public.questions (type, chapter, content, options, correct_answer, explanation) VALUES
('single', 'chapter_single', '注册登记安全检验时，机动车的整备质量应与机动车产品公告、机动车出厂合格证相符，(    )不超过±3%或±500kg。', '{"A": "大型客车", "B": "重中型挂车", "C": "货车", "D": "中型客车"}'::jsonb, 'B', ''),
