('multiple', 'chapter_multiple', '(    )的车辆不测试加载轴制动率和加载轴制动不平衡率。', '{"A": "采用钢板弹簧", "B": "采用空气悬架", "C": "总质量为整备质量1.2倍以下", "D": "非承载式车身"}'::jsonb, 'BC', ''),
('multiple', 'chapter_multiple', '送检车辆不应有与(    )的故障信息。', '{"A": "玻璃水报警", "B": "行车安全相关", "C": "ABS", "D": "EPS"}'::jsonb, 'BCD', ''),
('multiple', 'chapter_multiple', '安全技术检验时应先进行(    )后按检验流程开展检验。', '{"A": "联网查询", "B": "车辆唯一性检查", "C": "确认车辆无异常情形", "D": "核查送检机动车有效的机动车交通事故责任强制保险凭证(挂车以及实现电子保单、保险信息联网核查的除外）和机动车行驶证"}'::jsonb, 'ABC', ''),
('multiple', 'chapter_multiple', '检查轮胎花纹深度时，对(    )的转向轮使用轮胎花纹深度计测量。', '{"A": "大型客车", "B": "重中型货车", "C": "重中型载货专项作业车", "D": "危险货物运输车辆"}'::jsonb, 'ABCD', ''),
('multiple', 'chapter_multiple', '对发生过造成人员伤亡交通事故的送检机动车，人工检验时应重点检查损伤部位和损伤情况，属于使用年限在10年以内的非营运小型、微型载客汽车的，检验项目增加(    )。', '{"A": "车辆外观检查", "B": "驻车制动", "C": "底盘动态检验", "D": "车辆底盘部件检查"}'::jsonb, 'CD', ''),
('multiple', 'chapter_multiple', '对大型客车、重中型货车、重中型载货专项作业车、重中型挂车，在平整场地上使用钢直尺，在距地1.5m高度内，测量(    )和(    )上方的车身两侧对称部位。', '{"A": "第一轴", "B": "第二轴", "C": "第三轴", "D": "最后轴(对挂车仅测最后轴 )"}'::jsonb, 'AD', ''),
('multiple', 'chapter_multiple', '在用机动车安全检验时，重中型货车(半挂牵引车除外)、重中型载货专项作业车、重中型挂车外廓尺寸实测值不应超出(  )规定的限值，且与机动车行驶证记载的数值相比误差不超过±3%或±150mm。', '{"A": "GB 7258", "B": "GB 1589", "C": "GB    18565", "D": "GB 38900"}'::jsonb, 'AB', ''),
('multiple', 'chapter_multiple', '在用机动车安全检验时，重中型货车(半挂牵引车除外)、重中型载货专项作业车、重中型挂车外廓尺寸实测值不应超出GB 7258、GB 1589规定的限值，且与机动车行驶证记载的数值相比误差不超过(    )。', '{"A": "±3%", "B": "±5%", "C": "±150mm", "D": "±200mm"}'::jsonb, 'AC', ''),
('multiple', 'chapter_multiple', '注册登记安全检验时，机动车的轴距应与机动车产品公告、机动车出厂合格证相符，且误差不超过(    )。', '{"A": "±1%", "B": "±2%", "C": "±50mm", "D": "±100mm"}'::jsonb, 'AC', ''),
('multiple', 'chapter_multiple', '(    )驾驶人视区以外的车窗玻璃不应有穿孔或长度超过25mm的裂纹。', '{"A": "乘用车", "B": "专项作业车", "C": "客车", "D": "重中型货车"}'::jsonb, 'CD', ''),
('multiple', 'chapter_multiple', '前风窗玻璃(    )及驾驶人驾驶时用于观察(    )的可见光透射比应大于或等于70%。', '{"A": "所有部位", "B": "驾驶人视区部位", "C": "外后视镜的部位", "D": "车厢内货物的部位"}'::jsonb, 'BC', ''),
('multiple', 'chapter_multiple', '前照灯的远、近光光束变换功能应正常，(    )光照射位置不应出现异常偏(    )现象。', '{"A": "远", "B": "近", "C": "高", "D": "低"}'::jsonb, 'AC', ''),
('multiple', 'chapter_multiple', '同轴两侧应装用同一(    )的轮胎。', '{"A": "型号", "B": "规格", "C": "花纹", "D": "出厂日期"}'::jsonb, 'ABC', ''),
('multiple', 'chapter_multiple', '(    )的所有车轮及其他机动车的转向轮不应装用翻新的轮胎。', '{"A": "公路客车", "B": "旅游客车", "C": "校车", "D": "危险货物运输车辆"}'::jsonb, 'ABC', ''),
('multiple', 'chapter_multiple', '注册登记安全检验时，(    )应装用子午线轮胎。', '{"A": "乘用车", "B": "专项作业车", "C": "危险货物运输车辆", "D": "车长大于9m的客车"}'::jsonb, 'CD', ''),
('multiple', 'chapter_multiple', '使用号牌架辅助安装时，号牌架内侧边缘距离机动车登记编号字符边缘应大于5mm,不应使用(   )。', '{"A": "可拆卸号牌架", "B": "固定号牌架", "C": "可翻转号牌架", "D": "可移动号牌架"}'::jsonb, 'AC', ''),
('multiple', 'chapter_multiple', '总质量大于7500kg的(    )的前下部防护装置应正常有效。', '{"A": "半挂车", "B": "半挂牵引车", "C": "货车底盘改装的专项作业车", "D": "客车"}'::jsonb, 'BC', ''),
('multiple', 'chapter_multiple', '注册登记安全检验和在用机动车安全检验时，2019年1月1日起出厂的装备电涡流缓速器的汽车，电涡流缓速器的安装部位应设置(    )或(    )。', '{"A": "温度报警系统", "B": "自动喷淋装置", "C": "自动灭火装置", "D": "手动喷淋装置"}'::jsonb, 'AC', ''),
('multiple', 'chapter_multiple', '(    )无需转向轮横向侧滑量检验', '{"A": "客车", "B": "静态轴荷大于或等于11500kg、不适用于仪器设备检验的汽车", "C": "独立悬架的汽车", "D": "非营运小型、微型载客汽车"}'::jsonb, 'BCD', ''),
('multiple', 'chapter_multiple', '发现送检机动车有(    )时，检验机构及其检验员应详细登记该送检机动车的相关信息，拍照、录像固定证据，通过机动车安全
INSERT INTO public.questions (type, chapter, content, options, correct_answer, explanation) VALUES
('judge', 'chapter_judge', 'GB3847-2018标准适用于新生产柴油汽车下线检验、注册登记检验和在用汽车检验，也适用低速货车、三轮汽车以及其他装用压燃式发动机的汽车。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '正确（GB3847 - 2018适用范围 ）'),
('judge', 'chapter_judge', '在使用不透光烟度计进行测量时，采样探头插入排气管深度不得低于400mm。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（不透光烟度计采样深度要求 ）'),
('judge', 'chapter_judge', 'GB3847-2018标准规定了柴油车自由加速法和加载减速法排气污染物排放限值及测量方法，以及柴油车外观检验、OBD检查的方法和判定依据。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（GB3847 - 2018规定内容 ）'),
('judge', 'chapter_judge', '对于2018年5月1日以后生产车辆，如果0BD检验不合格，判定排放检验不合格。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '正确（2018年5月1日后车辆OBD不合格判定 ）'),
('judge', 'chapter_judge', '排气污染检测报告纸质档案保存期限应不少于3年，电子档案保存期限应不少于6年。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（档案保存期限，纸质和电子均不少于6年 ）'),
('judge', 'chapter_judge', '加载减速法功率扫描中，经修正的轮边功率测量结果不得低于制造厂规定的发动机额定功率的40%。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（加载减速轮边功率要求 ）'),
('judge', 'chapter_judge', 'GB3847-2018规定，按照规定的加载减速检测程序，检测最大轮边功率和相对应的发动机转速和转鼓表面线速度(VelMaxHP),并检测VelMaxHP点和80%VelMaxHP点的排气光吸收系数k及80%VelMaxHP点的氮氧化物。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（GB3847 - 2018加载减速检测参数规定 ）'),
('judge', 'chapter_judge', 'GB18258-2018标准中规定双怠速法的高怠速转速允差为±100r/min,发动机在高怠速转速工况时其λ值应在1±0.03或厂家规定的范围。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '（GB18258 - 2018双怠速法参数要求 双怠速法的高怠速转速允差为±200r/min,发动机在高怠速转速工况时其λ值应在1±0.05。）'),
('judge', 'chapter_judge', '加载减速法功率扫描中，经修正的轮边功率测量结果不得低于制造厂规定的发动机额定功率的40%。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（加载减速功率扫描要求 ）'),
('judge', 'chapter_judge', 'GB18258-2018和GB3847-2018规定：取样探头长度应保证能插入排气管深度不少于400mm,如果车辆排气系统自身设计导致取样探头的插入深度小于400mm,应使用延长管。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（采样探头深度及延长管要求 ）'),
('judge', 'chapter_judge', 'GB18285-2018标准中规定，在进行车辆尾气排放检测前检查发动机排气管、排气消声器和排气后处理装置的外观及安装紧固部位是否完好，如发现有腐蚀、漏气、破损和松动的，要求车主进行维修。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（GB18285 - 2018检测前检查要求 ）'),
('judge', 'chapter_judge', 'GB18285-2018标准中规定，对于变更登记、转移登记检验时应检查污染控制装置是否完好。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（GB18285 - 2018变更、转移登记检验要求 ）'),
('judge', 'chapter_judge', '对独立工作的双排气管车辆，应采用Y型取样管的对称双探头同时取样。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（双排气管车辆取样要求 ）'),
('judge', 'chapter_judge', 'GB18285-2018标准中规定，在进行车辆尾气排放检测前检查车辆是否存在严重烧机油或者严重冒黑烟现象，如有要求车主进行维修。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（GB18285 - 2018检测前检查要求 ）'),
('judge', 'chapter_judge', '对配有OBD系统的在用车，在完成外观检验后，应连接OBD诊断仪进行OBD 检查，在随后的排气污染物检测时可以断开。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（OBD检查在排气检测时应保持连接 ）'),
('judge', 'chapter_judge', '如果车辆污染控制装置被移除，但OBD故障指示灯未点亮报警，该车辆OBD应判定为合格。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（污染控制装置移除，OBD不合格 ）'),
('judge', 'chapter_judge', '如果排气污染物检测结果为负数或零时，应记录为“未检出”。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（检测结果记录要求 ）'),
('judge', 'chapter_judge', '检验机构应向生态环境主管部门实时传输检验信息。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（检验机构信息传输要求 ）'),
('judge', 'chapter_judge', '对于防侧滑装置失效的两驱小型微型载客汽油车，可以采用双怠速检测方法。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '正确（防侧滑失效车辆检测方法 ）'),
('judge', 'chapter_judge', '排气检查过程中，禁止使用降低排放控制装置功效的失效策略，所有针对污染物控制装置的篡改都属于排放检验不合格。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（排气检查篡改控制装置判定 ）'),
('judge', 'chapter_judge', '因发动机过热保护等特殊技术，车辆预热温度无法达到标准规定要求的，应最大限度接近标准规定的预热温度，并保证排气污染物检测前发动机启动至少 5 分钟以上，或按照制造厂说明书的规定进行检测。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（特殊预热情况检测要求 ）'),
('judge', 'chapter_judge', '检验机构气象站应安装在检测车间、电脑操作间内，并应与受检车辆、仪器处于相同的环境，测量记录排放检验时的环境数据。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '正确（气象站安装环境要求 ）'),
('judge', 'chapter_judge', 'HJ1237-2021标准规定，外观检验、OBD检查、排气污染物检测和项目应按照GB18285和GB3847进行，同一车辆或同型号车辆应采用同一种方法。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（HJ1237 - 2021检测方法一致性要求 ）'),
('judge', 'chapter_judge', '自由加速不透光烟度法检测前，应采用至少3次自由加速过程或其它等效方法对排气系统进行吹拂。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（自由加速烟度法检测前吹拂要求 ）'),
('judge', 'chapter_judge', '在进行自由加速测量时，必须在1s的时间内，将油门踏板连续完全踩到底，使供油系统在最短时间内达到最大供油量。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（自由加速测量操作要求 ）'),
('judge', 'chapter_judge', '自由加速检测过程应重复进行三次自由加速过程，烟度计应记录每次自由加速过程最大值，应将上述三次自由加速烟度最大值的算术平均值作为测量结果。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（自由加速检测结果计算要求 ）'),
('judge', 'chapter_judge', 'GB3847-2018规定：对于紧密型多驱动轴的车辆、全时四轮驱动车辆、无法中断车上主动型制动功能和扭矩控制功能的车辆，可以采用自由加速法进行排放测试。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（这类车辆适用自由加速法 ）'),
('judge', 'chapter_judge', '检验过程中车辆排放出现目视可见黑烟或蓝烟，按照GB18285和GB 3847判定外观检验不合格。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（出现黑烟应判定排放检验不合格 ）'),
('judge', 'chapter_judge', '依据HJ1237标准规定，检验机构应定期组织开展检验能力验证和比对试验，每年至少组织一次，每次进行比对试验结果和数据应记录保存归档。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（HJ1237能力验证要求每半年至少组织一次，每次进行比对试验结果和数据应记录保存归档 ）'),
('judge', 'chapter_judge', '在进行柴油车自由加速法检测时，不透光烟度计每天检测前应进行零点和满量程检查。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（不透光烟度计日常校准要求 ）'),
('judge', 'chapter_judge', '加载减速检测过程一般应在2min内完成，最长不能超过5min。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（加载减速检测时间要求 ）'),
('judge', 'chapter_judge', '在进行汽油车简易瞬态工况法检测时，排气分析仪每天开始检测前应进行取样系统密封性进行检查。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（汽油车简易瞬态工况法采样系统检查要求 ）'),
('judge', 'chapter_judge', 'GB3847-2018规定：在功率扫描，特别是排放测试过程中，如果排气中CO₂ 的浓度低于4%,检测程序应中止，并提示“检测停止-排放数据异常，请检查取样管”。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（GB3847 - 2018CO₂浓度异常处理6% ）'),
('judge', 'chapter_judge', 'HJ1237标准规定，排气分析仪采样管长度应小于7.5米，不透光烟度计采样管长度应小于3.5米，采样管不包括取样探头、过滤器。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '正确（HJ1237采样管长度要求 ）'),
('judge', 'chapter_judge', '轻型汽油车参加排气定期检测时，不需要监控油温和转速。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（轻型汽油车检测需监控油温、转速 ）'),
('judge', 'chapter_judge', 'GB18285-2018规定，对于两用燃料汽车，要求使用两种燃料分别进行排放检测。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（两用燃料汽车检测要求 ）'),
('judge', 'chapter_judge', '在用机动车排放检验是，若车辆排气管长度小于测量深度时，应使用加长管。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（排气管长度不足处理要求 ）'),
('judge', 'chapter_judge', '为保证测量结果的准确性，每天开始检测前都应使用低浓度标准气对CO、HC、CO₂进行精度检查。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（检测前精度检查要求 ）'),
('judge', 'chapter_judge', 'GB3847-2018规定若采用转化炉将NO₂转变为NO时，转换效率应≥90%,并对转化效率做定期检验。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（GB3847 - 2018转化效率要求 ）'),
('judge', 'chapter_judge', '在进行自由加速测量时，必须在1秒的时间内，将油门踏板连续完全踩到底，并保持2秒以上，使供油系统在最短时间内达到最大供油量。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（自由加速测量操作时间等要求不符 ）'),
('judge', 'chapter_judge', '测功机在加载过程中发动机温度过高会导致发动机故障，因此需要轴流风机强制对发动机扇热。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（测功机加载散热要求不符 ）'),
('judge', 'chapter_judge', '加载减速工况法功率扫描是油门踩到底待车速稳定后其车速最接近70km/h开始扫描。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（加载减速功率扫描起始车速等要求不符 ）'),
('judge', 'chapter_judge', '双怠速检测中高怠速是指用油门踏板将发动机转速稳定控制在3500r/min额定转速', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（双怠速法高怠速转速要求不符 ）'),
('judge', 'chapter_judge', 'GB18285-2018中规定，2011年7月1日以后生产的轻型汽油车和2013年7月1日以后生产的重型汽油车要强制OBD检测。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（特定汽油车强制OBD检测要求 ）'),
('judge', 'chapter_judge', 'GB3847-2018中要求，加载减速检测中，如果环境温度超过42°应终止检测。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（加载减速检测环境温度终止要求 45度 ）'),
('judge', 'chapter_judge', '日常检查中泄漏检查时，仅需要对任意一个取样管进行泄漏检查通过即可。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（泄漏检查需所有取样管 ）'),
('judge', 'chapter_judge', '对紧密型多驱动轴车辆，或全时四轮驱动车辆等不能按加载减速法进行试验的车辆可按自由加速法进行检测。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（特殊车辆检测方法 ）'),
('judge', 'chapter_judge', '根据GB18285-2018的规定，2010年7月1日以后生产的轻型汽油车，如果OBD检查不合格时，也判定排放检验结果不合格。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（GB18285 - 2018特定轻型汽油车OBD不合格判定 ）'),
('judge', 'chapter_judge', '根据GB18285-2018的规定，在外观检验过程中，当发现车辆排气污染控制装置不齐全，可进行进行排气污染测试，待检测合格后，告知车主及时维修。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（GB18285 - 2018外观检验发现控制装置不全处理 ）'),
('judge', 'chapter_judge', '环境参数测量设备应放置在仪器操作间，利用空调保温保湿。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（环境参数测量设备放置及环境控制要求 ）');
INSERT INTO public.questions (type, chapter, content, options, correct_answer, explanation) VALUES
('judge', 'chapter_judge', '当检测车间温度过低，可人工给环境参数测量设备进行加温，检测系统记录加温后的数据，确保能够正常开展检测。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（检测车间加温及数据记录不符合规范 ）'),
('judge', 'chapter_judge', '不透光烟度计在进行满量程检查时，可以使用手指头代替满量程遮光片进行，只要能够通过满量程检查即可。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（不透光烟度计满量程检查需用标准遮光片 ）'),
('judge', 'chapter_judge', '分析仪泄漏检查时，可以通过折管的方式完成检查，无须使用专业堵帽。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（分析仪泄漏检查需用专业堵帽 ）'),
('judge', 'chapter_judge', '当底盘测功机日常检查项目不合格时，可以通过修改检测系统的设置，人工跳过日常检查的锁止，正常开展检测工作。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（底盘测功机日常检查不合格不能人工跳过 ）'),
('judge', 'chapter_judge', '两用燃料汽车指既能燃用汽油又能燃用一种气体燃料，也可以同时燃用两种燃料的汽车。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（两用燃料汽车定义理解有误，表述不准确 ）'),
('judge', 'chapter_judge', '双怠速法测量中，对于双排气管车辆，应取各排气管测量结果的算术平均值。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（双怠速法双排气管车辆结果处理 ）'),
('judge', 'chapter_judge', '双怠速法测量时，如果C0与CO₂浓度之和小于6%,则测试结果可能无效。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（双怠速法CO与CO₂浓度和的有效性判定 ）'),
('judge', 'chapter_judge', '双怠速法测量时，发动机的冷却液温度对测量结果没有影响。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（双怠速法测量时，发动机冷却液温度对结果有影响 ）'),
('judge', 'chapter_judge', '公路客车、旅游客车和校车的所有车轮及其他机动车的转向轮不可以装用翻新的轮胎。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（公路客车等转向轮装翻新轮胎的规定 ）'),
('judge', 'chapter_judge', '罐式危险货物运输车辆的罐体及罐体上的管路和管路附件不应超出车辆的侧面及后下部防护装置，且罐体后封头及罐体后封头上的管路和管路附件外端面与后下部防护装置内侧在车辆长度方向垂直投影的距离应大于或等于150 mm。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（罐式危险货物运输车辆管路及防护要求 ）'),
('judge', 'chapter_judge', '2018年1月1日起出厂的罐式危险货物运输车辆，若罐体顶部无任何附属设备设施或附属设备设施未露出罐体，也应设置倾覆保护装置', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（2018年1月1日起罐式危险货物运输车辆保护装置要求 ）'),
('judge', 'chapter_judge', '注册登记安全检验和在用机动车安全检验时，用于运输液体危险货物的罐式危险货物运输车辆应按GB 18564.1、GB18564.2等规定安装紧急切断装置。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（罐式危险货物运输车辆紧急切断装置安装要求 ）'),
('judge', 'chapter_judge', '注册登记安全检验时，2019年1月1日起出厂的车辆的紧急切断装置自动关闭或提示报警功能应符合GB 7258的要求。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（2019年1月1日起车辆紧急切断装置功能要求 ）'),
('judge', 'chapter_judge', '非营运小型汽车唯一性检查、车辆特征参数检查、车辆外观检查、安全装置检验等车场外检最少检验时间为120秒。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（非营运小型汽车外检最少检验时间规定 ）'),
('judge', 'chapter_judge', '传动轴在运转时不允许发生振抖和异响，中间轴承和万向节不允许有裂纹和松旷现象。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（传动轴运行要求 ）'),
('judge', 'chapter_judge', '底盘部件检查时，减震器应齐全有效，不允许有明显渗漏油现象。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（底盘部件减振器要求 ）'),
('judge', 'chapter_judge', 'GB38900规定，危险货物运输车及车长大于9m的其它客车应装用无内胎子午线轮胎。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（GB38900对危险货物运输车及大客车轮胎要求 ）'),
('judge', 'chapter_judge', '检验机动车转向信号灯，工作应正常，且光色为黄色。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（转向信号灯光色应为琥珀色 ）'),
('judge', 'chapter_judge', '平头或短头小型、微型载客汽车就是面包车。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（平头/短头小型、微型载客汽车与面包车定义有区别 ）'),
('judge', 'chapter_judge', '依据GB13392-2023标准专门用于运送易燃和易爆物品的道路运输危险货物车辆，应在驾驶室上方安装红色标志灯。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（GB13392 - 2023对危险货物运输车标志灯要求 ）'),
('judge', 'chapter_judge', '在用机动车检验时，客车出口不应安装有保护装置意外的其他固定、锁止应急门的装置。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（在用机动车检验客车出口装置要求 ）'),
('judge', 'chapter_judge', '所有集装箱车、集装箱运输半挂车的载货部位应采用骨架式结构，集装箱应用焊接等方式与骨架成为一体。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（集装箱车辆结构要求不符，应采用骨架式结构 ）'),
('judge', 'chapter_judge', '厢式载货车辆的货厢的顶部应封闭、不可开启(翼开式车辆除外),其与侧面的连接应采用焊接等永久固定的方式：货厢的后面或侧面应设有固定位置的车门。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（厢式载货车辆货厢要求 ）'),
('judge', 'chapter_judge', '注册登记安全检验时，仓栅式载货车辆的载货部位的顶部应安装有与侧面栅栏可拆卸和调整的顶棚杆。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（仓栅式载货车辆顶棚杆要求 ）'),
('judge', 'chapter_judge', '2018年1月1日起出厂的封闭式货车都应配备板式隔离装置。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（2018年1月1日起封闭式货车隔离装置要求 ）'),
('judge', 'chapter_judge', '新能源汽车应具有外接充电接口、且充电接口表面不应有明显变形或灼烧痕迹。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（新能源车充电接口要求 ）'),
('judge', 'chapter_judge', '2017年1月1日起出厂的汽车(无驾驶室的三轮汽车除外)应配备1件汽车乘员反光背心。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（2018年1月1日起汽车反光背心要求 ）'),
('judge', 'chapter_judge', '2013年1月1日起出厂的发动机后置的客车(专用校车除外),应装备发动机舱自动灭火装置。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（2013年5月1日起客车自动灭火装置要求 ）'),
('judge', 'chapter_judge', '客车、重中型货车、重中型载货专项作业车驾驶室内应设置防止阳光直射而使驾驶人产生炫目的装置。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（驾驶室内防眩光装置要求 ）'),
('judge', 'chapter_judge', '在用机动车安全检验时，总质量大于或等于7500kg的自卸车还应在车厢左右两侧喷涂放大的号牌号码。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（自卸车喷放大牌号要求 ）'),
('judge', 'chapter_judge', '轮胎的胎面、胎壁不应有长度超过25mm或深度足以暴露出轮胎帘布层的破裂和割伤及其他影响使用的缺损、异常磨损和变形。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（轮胎损伤要求 ）'),
('judge', 'chapter_judge', '2019年1月1日起出厂的装备电涡流缓速器的汽车，电涡流缓速器的安装部位应设置温度报警系统或自动灭火装置。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（2019年1月1日起电涡流缓速器车辆温度报警要求 ）'),
('judge', 'chapter_judge', '不合格项目复检时需再次确认车辆识别代号。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（不合格项目复检要求 ）'),
('judge', 'chapter_judge', '底盘动态检验是指在行驶状态下，定性地判断送检机动车的转向、传动、制动、仪表和指示器是否符合运行安全要求。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确'),
('judge', 'chapter_judge', '机动车检验出现人工检验不合格的情形时，检验员应停止进行其他检验项目的检验。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '正确（人工检验不合格处理 ）'),
('judge', 'chapter_judge', '对发生过交通事故的送检机动车，应根据交通事故时送检机动车的损伤部位和损伤情况确定需重点检查的部位和项且.', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（交通事故车辆检验重点确定 ）'),
('judge', 'chapter_judge', '货车(三轮汽车除外)、专项作业车、挂车在底盘部件检查时，最少录像时间为100秒。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '错误（货车等底盘部件检查最少录像时间要求不符 ）'),
('judge', 'chapter_judge', '小型载客汽车(面包车除外)前照灯远光发光强度检测不合格，但经确认确实属于前照灯检测仪与车辆前照灯技术不匹配，经授权签字人确认后视同合格，并记录在检验表中。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（前照灯检测特殊情况判定 ）'),
('judge', 'chapter_judge', '汽车(无驾驶室的三轮汽车除外)应配备三角警告牌和灭火器。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '正确（汽车安全装备要求 ）'),
('judge', 'chapter_judge', '挂车或使用电子控制装置的汽车，不检验驻车制动。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '错误（挂车等需检验驻车制动 ）'),
('judge', 'chapter_judge', '为了夜间行车安全，车辆允许加装后射灯。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（车辆夜间行驶加装后射灯规定不符 ）'),
('judge', 'chapter_judge', '车辆底盘部件检验时，转向器、转向油泵、转向油管等不应有漏油现象。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（底盘部件漏油要求 ）'),
('judge', 'chapter_judge', 'GB38900-2020规定，机动车设置的喇叭应能有效发声；教练车(三轮汽车除外)还应设置辅助喇叭开关，其工作应可靠。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（GB38900 - 2020喇叭及教练车要求 ）'),
('judge', 'chapter_judge', '2018年1月1日起出厂的封闭式货车都应配备板式隔离装置。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（2018年1月1日起封闭货车要求 ）'),
('judge', 'chapter_judge', '2018年1月1日起出厂的装备电涡流缓速器的汽车，电涡流缓速器的安装部位应设置温度报警系统或自动灭火装置。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '正确（2018年1月1日起电涡流缓速器车辆要求 ）'),
('judge', 'chapter_judge', '在用机动车安全检验时，如打刻(或铸出)的发动机号码/驱动电机号码不易见，且易见部位或覆盖件上的发动机/驱动电机标识缺失的，使用内窥镜等工具进一步确认。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（在用机动车唯一性检查要求 ）'),
('judge', 'chapter_judge', '车辆唯一性检查是指：对机动车的号牌号码和类型、车辆品牌和型号、车辆识别代码(出厂整车厂编号)、发动机号码(或电动机号码)、车辆颜色和外形进行检查，以确认送检机动车的唯一性。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（车辆唯一性检查内容 ）'),
('judge', 'chapter_judge', '重型汽车的唯一性检查、车辆特征参数检查、车辆外观检查、安全装置检测最少检验时间为240秒。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', ''),
('judge', 'chapter_judge', '公路客车、旅游客车、设有乘客站立区的客车、校车和发动机中置且宽高比小于等于0.9的乘用车所有车窗玻璃的可见光透射比均应大于等于50%。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', ''),
('judge', 'chapter_judge', '机动车转向。系统的转向节及臂，转向横、直拉杆及球销应连接可靠，且不应有裂纹和损伤，并且转向球销不应松旷；为了增加横直拉杆的强度、提高安全可靠性，可以对横直拉杆进行焊接加固。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（转向横拉杆不能进行焊接加固 ）');
INSERT INTO public.questions (type, chapter, content, options, correct_answer, explanation) VALUES
('judge', 'chapter_judge', '道路运输爆炸品和剧毒化学品车辆的驾驶室内应配备1个干粉灭火器，在车辆两边应配备与所装载介质性能相适应的灭火器各两个。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（道路运输危险化学品车辆灭火器配备要求不符 ）'),
('judge', 'chapter_judge', '根据GB38900标准规定，所有栏板货车应在驾驶室(区)两侧喷涂栏板高度，喷涂的中文及阿拉伯数字应清晰，高度应大于等于80mm。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（GB38900栏板货车喷涂要求 ）'),
('judge', 'chapter_judge', '安全技术检验时应先进行联网查询、车辆唯一性检查，确认车辆无异常情形后按检验流程开展检验。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（安全技术检验流程 ）'),
('judge', 'chapter_judge', '在用机动车安全检验时，不应出现座垫套覆盖遮挡安全带、安全带绑定在座位下面、使用安全带插扣等情形。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（机动车安全带使用要求 ）'),
('judge', 'chapter_judge', '根据GB38900-2020的规定，使用时间在10年以内的未发生过人员伤亡交通事故的的非营运的小型、微型载客汽车，人工检验时不需要进行底盘动态检验和车辆底盘部件检查。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '正确（GB38900 - 2020特定车辆检验要求 ）'),
('judge', 'chapter_judge', '根据GB7258—2017的规定，2018年1月1日起出厂的总质量大于4500kg的货车、货车底盘改装的专项作业车应安装前下部防护装置。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', ''),
('judge', 'chapter_judge', '2019年1月1日起出厂的危险货物运输货车、公路客车、旅游客车和未设置乘客站立区的公共汽车应装备单燃油箱，且单燃油箱的容积应小于或等于500L。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（2019年1月1日起相关车辆油箱容积要求不符，应为≤400L ）'),
('judge', 'chapter_judge', '在用机动车安全检验时，送检机动车空车质量检验不合格的，检验机构及其检验员应结合允许加装的部件(如：防风罩、水箱、工具箱、备胎架、起重尾板等)、维修情况、随车工具等开展重点核查；有非法改装嫌疑的，按照规定处理。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（空车质量检验不合格处理 ）'),
('judge', 'chapter_judge', '车辆宽度大于2100mm的机动车应安装示廓灯，示廓灯的颜色应为红色。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（车辆示廓灯颜色应为黄色 ）'),
('judge', 'chapter_judge', '自学用车进行安全技术检验时，需检验副制动踏板和辅助后视镜，其他检验项目与教练车一致。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（自学用车检验项目要求不符 ）'),
('judge', 'chapter_judge', '罐式危险货物运输车辆罐体上的管路和管路附件不应超出车辆的侧面及后下部防护装置，且罐体后封头及罐体后封头上的管路和管路附件外端面与后下部防护装置内侧在车辆长度方向垂直投影的距离应大于或等于100mm。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '正确（罐式危险货物运输车辆管路要求 ）'),
('judge', 'chapter_judge', '根据GB 38900-2020的要求，驻车制动使用电子控制装置的汽车，不检验驻车制动。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', ''),
('judge', 'chapter_judge', '安检所有检验项目应一次检验完毕，出现不合格项时应继续进行其他项目的检验，但不适宜继续进行检验的项目除外。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（安检项目检验流程 ）'),
('judge', 'chapter_judge', '在进行侧滑检测时，不得转动方向盘。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（侧滑检测操作要求 ）'),
('judge', 'chapter_judge', '在用机动车安全检验时，送检机动车的车身颜色、车辆外形应与机动车行驶证上的车辆照片一致(目视不应有明显区别),不应有更改车身颜色、改变车厢形状、改变车辆结构等情形。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（在用机动车外观要求 ）'),
('judge', 'chapter_judge', '在用机动车安全检验时，机动车的座位(铺位)数应与机动车行驶证签注的内容一致，座椅布置和固定方式应无改装情形。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（机动车座椅要求 ）'),
('judge', 'chapter_judge', '注册登记安全检验和在用机动车安全检验时，保险杠、后视镜、下视镜等部件应完好，灯具不应破损、缺失。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（机动车部件完好要求 ）'),
('judge', 'chapter_judge', '注册登记安全检验和在用机动车安全检验时，喷涂、粘贴的标识或车身广告不应影响安全驾驶。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（机动车标识要求 ）'),
('judge', 'chapter_judge', '采用密闭钢化玻璃式应急窗的客车，在相应的应急窗邻近应配备一个应急锤或采用自动破窗装置。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', ''),
('judge', 'chapter_judge', '只有对方向盘最大自由转动量有疑问时才使用设备测量，不需要记录测量值。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（设备测量要求不符，需记录测量值 ）'),
('judge', 'chapter_judge', '底盘动态检验时，以不低于10km/h的速度正直行驶，急踩制动后迅速放松，检验制动效果是否异常。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（底盘动态检验速度要求不符，应为不低于20km/h ）'),
('judge', 'chapter_judge', '车长大于7.5m的客车可以设置车外顶行李架，其车外顶行李架长度不应超过车长的1/3且高度不应超过300mm。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（客车车顶行李架要求不符，长度不应超过车长的1/2 ）'),
('judge', 'chapter_judge', '检测员在进行车辆底盘部件检查时，对转向系部件的检查需要引车员的配合才能完成。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（底盘部件检查配合要求 ）'),
('judge', 'chapter_judge', '“排气管、消声器的安装牢固定以及排气管口的指向”属于底盘检查的行驶系部件项目。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（“排气管等”归属行驶系部件要求不符 ）'),
('judge', 'chapter_judge', '机动车设置的喇叭能否有效发声、重型货车的右转弯音响提示装置的配置和工作情况、可见电器导线的布置捆扎固定等都属于外部照明和信号装置的检查项目。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（外部照明和信号装置检查内容 ）'),
('judge', 'chapter_judge', '2020年1月1日起机动车安全检验时，汽车(无驾驶室的三轮汽车除外)应配备1件汽车乘员反光背心。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '正确（2018年1月1日起汽车反光背心要求 ）'),
('judge', 'chapter_judge', '在用机动车检验时，配备的汽车安全带应完好且能正常使用，不得出现“座垫套覆盖遮挡安全带”、“安全带绑定在座位下面”。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（机动车安全带使用要求 ）'),
('judge', 'chapter_judge', '制动系应无擅自改动，不应从制动系统获取气源作为加装装置的动力源。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（制动系统要求 ）'),
('judge', 'chapter_judge', '专门用于运送易燃和易爆物品的危险货物运输车，排气管应装在罐体/箱体前端面之前、不高于车辆纵梁上平面的区域。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（危险货物运输车排气管要求 ）'),
('judge', 'chapter_judge', '对机动车底盘动态检验，引车员须操作车辆，起步并行驶20m以上进行检查。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（底盘动态检验操作要求 ）'),
('judge', 'chapter_judge', '底盘部件检查时，需有辅助人员配合检查即可，无需引车员在驾驶室
INSERT INTO public.questions (type, chapter, content, options, correct_answer, explanation) VALUES
('judge', 'chapter_judge', '前照灯检测过程中，车辆发动机应保持运转状态，以保证车辆电源处于充电状态，使前照灯处于正常工作状态。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（前照灯检测车辆状态要求 ）'),
('judge', 'chapter_judge', '对于前照灯检验项目中出现不合格的，复检所有前照灯。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（前照灯复检要求 ）'),
('judge', 'chapter_judge', '为了操作方便，行车制动的控制装置与驻车制动的控制装置可以结合在一起。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（行车与驻车制动控制装置应相互独立 ）'),
('judge', 'chapter_judge', '轴荷超过检验设备允许承载能力的车辆、多轴无法上线的车辆、全时四驱车辆不进行线内制动检验，应路试。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '正确（特定车辆制动检验要求 ）'),
('judge', 'chapter_judge', '对全时四驱车辆、具有驱动防滑控制功能的车辆不用上线检测制动性能。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', ''),
('judge', 'chapter_judge', '外廓尺寸项目检验，在用机动车不查验，只针对注册登记车辆检验。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '正确（外廓尺寸检验范围 ）'),
('judge', 'chapter_judge', '整备质量项目检验，在用机动车不查验，只针对注册登记车辆查验。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', ''),
('judge', 'chapter_judge', '采用滚筒反力式制动检验台检验时，轴制动率为测得的该轴左、右车轮最大制动力之和与该轴(静态)轴荷之百分比。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', ''),
('judge', 'chapter_judge', '用滚筒反力式制动台检验时，起动滚筒电机，稳定2s后实施制动，制动踏板急踩到底。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（滚筒反力式制动台检验操作要求不符，稳定1s后实施制动 ）'),
('judge', 'chapter_judge', '通过举升台体对测试轴加载，举升至副滚筒上母线离地100mm或轴荷达到11500kg时停止举升。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '错误（举升台停止举升条件不符 ）'),
('judge', 'chapter_judge', '台式制动检验，对总质量小于等于整备质量1.2倍的专项作业车，制动力总和与整车重量的百分比应大于等于50%。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '错误（台试制动检验要求不符 ）'),
('judge', 'chapter_judge', '四灯制前照灯中有两只灯的发光强度达到两灯制要求，就视为合格。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（四灯制前照灯合格判定不符 ）'),
('judge', 'chapter_judge', '同一轴上的轮胎规格和花纹应相同，轮胎规格应符合整车制造厂的出厂规定。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（轮胎规格要求 ）'),
('judge', 'chapter_judge', '减振器应齐全有效，不允许有明显渗漏油现象。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（减振器要求 ）'),
('judge', 'chapter_judge', '车长大于6m或总质量大于4500kg的货车、挂车，其车身(车厢)后部喷涂符合规定的放大牌号。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '错误（车辆喷放大牌号要求不符，部分车型有规定 ）'),
('judge', 'chapter_judge', '前风窗玻璃及风窗以外玻璃用于驾驶员视区部位的可见光透射比不小于70%。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', ''),
('judge', 'chapter_judge', '所有校车、公路客车和旅游客车安装符合规定的汽车行驶记录仪', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（特定客车行驶记录仪要求 ）'),
('judge', 'chapter_judge', '专门用于运送易燃和易爆物品的道路运输危险货物车辆，应在驾驶室上方安装红色标志灯。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '正确（GB13392 - 2023对危险货物运输车标志灯要求 ）'),
('judge', 'chapter_judge', '道路运输爆炸品和剧毒化学品车辆，必须在后部或两侧粘贴能标示出车辆轮廓、宽度为150mm±20mm的橙色反光带。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（道路运输危险化学品车辆粘贴标识宽度要求不符，应为150mm±20mm 等规范 ）'),
('judge', 'chapter_judge', '栏板货车和自卸车应在车厢两侧喷涂栏板高度。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', ''),
('judge', 'chapter_judge', '栏板挂车应在车厢两侧喷涂栏板高度。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '错误（栏板货车喷涂要求不符 ）'),
('judge', 'chapter_judge', '联网查询主要是查询送检机动车是否发生过交通事故及涉及尚未处理完毕的道路交通安全违法行为。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '正确（联网查询内容 ）'),
('judge', 'chapter_judge', '机动车车身前部外表面的易见部位上应至少装置一个能永久保持的商标或厂标。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（机动车商标/厂标要求 ）'),
('judge', 'chapter_judge', '专用校车及客车可设置的车外顶行李架不能超过车长的百分之三十。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（专用校车等车顶行李架要求不符，长度不应超过车长的1/2 ）'),
('judge', 'chapter_judge', '外廓尺寸自动测量装置检验时，应使用符合标准的机动车外廓尺寸自动测量装置，自动测量装置必要时可以人工修改设备无法剔除的测量数据和照片的功能。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（外廓尺寸自动测量装置要求不符，自动测量装置数据不能人工修改 ）'),
('judge', 'chapter_judge', '货车货箱(自卸车、装载质量1000 kg以下的货车除外)前部是否安装有比驾驶室高至少50 mm的安全架。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '正确（货车安全架要求 ）'),
('judge', 'chapter_judge', '在车辆行驶过程中需检查离合器接合是否平稳，有无异响、打滑、抖动、沉重、分离不彻底等现象。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（车辆行驶中离合器检查要求 ）'),
('judge', 'chapter_judge', '制动灯的反光强度应明显亮于后位灯的反光强度。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（制动灯与后位灯反光强度要求 ）'),
('judge', 'chapter_judge', '总质量大于或等于12000kg的自卸车应在车厢左右两侧喷涂放大的号牌号码。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', ''),
('judge', 'chapter_judge', '传动轴在运转时不允许发生振抖和异响，中间轴承和万向节不允许有裂纹和松旷现象', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（传动轴要求 ）'),
('judge', 'chapter_judge', '四灯制是指具有四只前照灯车辆。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（四灯制定义不符 ）'),
('judge', 'chapter_judge', '所有货车(半挂牵引车、多用途货车除外)、货车底盘改装的专项作业车和挂车(旅居挂车除外)应在后部和侧面设置车身反光。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', ''),
('judge', 'chapter_judge', '乘用车、挂车轮胎胎冠花纹上的花纹深度应大于等于1.6mm,摩托车轮胎胎冠花纹上的花纹深度应大于等于0.8mm;其他机动车转向轮的胎冠花纹深度应大于等于3.2mm,其余轮胎胎冠花纹深度应大于等于1.6mm。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（轮胎花纹深度要求 ）'),
('judge', 'chapter_judge', '前风窗玻璃驾驶人视区部位及驾驶人驾驶时用于观察外后视镜的部位的可见光透射比应大于等于50%。所有车窗玻璃不应张贴镜面反光遮阳膜。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（前风窗玻璃透光率要求不符，驾驶人视区及观察外后视镜部位应≥70% ）'),
('judge', 'chapter_judge', '前风窗玻璃驾驶人视区部位及驾驶人驾驶时用于观察外后视镜的部位的可见光透射比应大于等于70%。所有车窗玻璃不应张贴镜面反光遮阳膜。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', ''),
('judge', 'chapter_judge', '检测车身高度差时，在距地1.5m高度内，测量第一轴和最后轴上方的车身两侧对称部位的高度，计算高度差。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（检测车身高度差要求 ）'),
('judge', 'chapter_judge', '车辆唯一性检查是指对机动车的号牌号码和分类、车辆品牌和型号、车辆识别代号(或整车出厂编号)、发动机号码/驱动电机号码、车身颜色和车辆外形等特征进行检查，以确认送检机动车的唯一性。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（车辆唯一性检查内容 ）'),
('judge', 'chapter_judge', '对于因更换发动机、车身或者车架申请变更登记的机动车检验时，参照注册登记机动车安全检验项目。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '正确（变更登记车辆检验要求 ）'),
('judge', 'chapter_judge', '检查传动系的“悬架”时，对于钢板弹簧，检视有无裂纹、缺片、加片、断裂、塑性变形和功能失效等现象。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '正确（悬架检查要求 ）'),
('judge', 'chapter_judge', '对车辆行车制动动态检验时，以20km/h车速正直行驶，急踩制动踏板后使车辆停车，应无明显跑偏现象。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '正确（行车制动动态检验要求 ）'),
('judge', 'chapter_judge', '安全技术检验时应先进行联网查询、车辆唯一性检查，确认车辆无异常情形后按检验流程开展检验。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（安检流程 ）'),
('judge', 'chapter_judge', '教练车应在车身两侧及后部喷涂有高度大于或等于100 mm的“教练车”字样。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（教练车喷涂要求 ）'),
('judge', 'chapter_judge', '总质量大于7500 kg的货车、货车底盘改装的专项作业车装备的前下部防护装置应正常有效。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（特定专项作业车前下部防护装置要求 ）'),
('judge', 'chapter_judge', '转向器、转向油泵、转向油管等不应有漏油现象。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（转向系统漏油要求 ）'),
('judge', 'chapter_judge', '车桥与悬架之间的拉杆和导杆不应松旷和移位，减振器可以漏油，杆衬套不应出现开裂、与销轴分离等现象。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（车桥与悬架要求不符，减振器不应漏油 ）'),
('judge', 'chapter_judge', '制动主缸、轮缸、管路等不应漏气、漏油，制动软管不应有明显老化、开裂、被压扁、鼓包等现象。', '{"A": "正确", "B": "错误"}'::jsonb, 'A', '正确（制动系统要求 ）'),
('judge', 'chapter_judge', '所有车辆车用轮胎应有胎面磨耗标志。', '{"A": "正确", "B": "错误"}'::jsonb, 'x', '正确（轮胎磨损标志要求 ）'),
('judge', 'chapter_judge', '所有载货汽车和挂车均应安装侧面防护。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '正确（载货汽车侧面防护要求 ）'),
('judge', 'chapter_judge', '一辆所有轮胎胎冠花纹深度均为2.5mm中型客车，该车轮胎的外观合格。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '错误（轮胎花纹深度要求不符，中型客车转向轮花纹深度应≥3.2mm ）'),
('judge', 'chapter_judge', '大中型客车、货车、专项作业车、挂车在进行车辆底盘部件检查时要使用底盘间隙仪。', '{"A": "正确", "B": "错误"}'::jsonb, 'B', '正确（大型车辆底盘部件检查要求 ）');
